 const lower=filename(file).toLowerCase();
 if(/flux|sd3|stable[-_ ]?diffusion[-_ ]?3|lora|controlnet|refiner|inpaint|turbo|lcm/.test(lower))return {id:file,name:filename(file).replace(/\.(safetensors|ckpt)$/i,''),file,installedFile:file,family:'Other',creator:'Your local server',description:'The filename suggests a model that needs a specialized workflow. Check its model card.',compatible:false,installed:true};
