 return {id:file,name:filename(file).replace(/\.(safetensors|ckpt)$/i,''),file,installedFile:file,family,creator:'Your local server',description:family==='Unknown'?'The server lists this checkpoint, but its family is unverified. Confirm it is a full SD 1.5 or SDXL checkpoint with a VAE before using it.':'Family estimated from the filename. Check the model card to confirm it is a standard full checkpoint.',compatible:null,installed:true};
