function renderModelBrowser(){
 const root=$('model-grid');root.replaceChildren();$('installed-count').textContent=state.connected?state.models.length:'0';$('discover-count').textContent=modelCatalog.length;
 $('refresh-models').disabled=browserState.refreshing||state.busy;$('refresh-models').innerHTML=icon('refresh')+(browserState.refreshing?'Refreshing…':'Refresh installed');
 $('models-intro').textContent=browserState.collection==='discover'?'Full checkpoints selected for this studio. Download once, create locally.':state.connected?'Checkpoints reported by '+new URL(state.server).host+'.':'Connect your ComfyUI server to see its checkpoints.';
 $('browser-status').textContent=browserState.collection==='discover'?'Curated checkpoints · Hugging Face downloads':state.connected?'Live server list · '+state.models.length+' checkpoints':'No server connected';
 if(browserState.collection==='installed'&&!state.connected){$('model-result-count').textContent='0 installed models';createBrowserEmpty('Your models live on your machine.','Connect your running ComfyUI server to browse installed checkpoints. New to local models? The setup guide will get you there.',openConnection,'Connect server');return;}
 const all=browserState.collection==='discover'?modelCatalog:state.models.map(classifyInstalledModel);
 const query=browserState.query.trim().toLowerCase();const visible=all.filter(m=>(browserState.family==='all'||m.family===browserState.family)&&(!query||[m.name,m.creator,m.file,m.family,m.description,m.best||''].join(' ').toLowerCase().includes(query)));
 $('model-result-count').textContent=`${visible.length} ${visible.length===1?'model':'models'}${query||browserState.family!=='all'?' found':''}`;
 if(!visible.length){if(all.length)createBrowserEmpty('No models match those filters.','Try another name or reset the filters.',()=>{browserState.query='';browserState.family='all';$('model-search').value='';$('model-family').value='all';renderModelBrowser();},'Clear filters');else createBrowserEmpty('Connected, but no checkpoints yet.','Put a complete checkpoint in ComfyUI/models/checkpoints, restart ComfyUI, then refresh this list.',()=>startTutorial(guideState.modelId,2),'Show installation steps');return;}
 for(const m of visible){
  const match=m.installed?m.installedFile:installedMatch(m);const selected=state.connected&&match===$('model').value;const card=document.createElement('article');card.className='model-card catalog-card'+(selected?' model-selected':'');card.dataset.modelId=m.id;
  const badge=m.compatible===false?'Different workflow':match?(m.family==='Unknown'?'Installed · unverified':m.compatible===null?'Installed · inferred':'Installed'):m.recommended?'Good first model':m.family==='Unknown'?'Check compatibility':'Full checkpoint';
  card.innerHTML=`<div class="catalog-card-top"><span class="model-symbol">${icon('box')}</span><span class="model-card-badge${match?' installed-badge':''}${m.compatible===false?' unsupported-badge':''}">${badge}</span></div><div class="model-family-tag">${escapeHTML(m.family)}${m.gb?' · '+escapeHTML(m.gb):''}</div><h2>${escapeHTML(m.name)}</h2><span class="model-creator">${escapeHTML(m.creator)}</span><p>${escapeHTML(m.description)}</p><div class="model-card-facts"><span>${icon(m.memory?'monitor':'info')}</span><span>${escapeHTML(m.memory||'Family inferred from filename')}</span></div>${!m.installed&&m.repo?`<a class="button primary catalog-download" href="${modelDownload(m)}" target="_blank" rel="noopener noreferrer" aria-label="Download ${escapeHTML(m.name)} checkpoint, ${m.gb}">${icon('download')} Download checkpoint <span>${m.gb}</span></a>`:''}<div class="catalog-actions"><button class="button primary model-main-action"></button><button class="button model-details-button">Details</button></div>`;
  const action=card.querySelector('.model-main-action');action.textContent=m.compatible===false?'Needs another workflow':match?(selected?'Open in studio':'Use model'):'Install & start';action.disabled=m.compatible===false||state.busy;action.onclick=()=>match?useInstalledModel(match):startTutorial(m.id,1);
  card.querySelector('.model-details-button').onclick=()=>openModelDetails(m);root.append(card);
 }
}
window.renderModelBrowser=renderModelBrowser;
$('discover-tab').onclick=()=>setModelCollection('discover');$('installed-tab').onclick=()=>setModelCollection('installed');$('model-search').oninput=e=>{browserState.query=e.target.value;renderModelBrowser();};$('model-family').onchange=e=>{browserState.family=e.target.value;renderModelBrowser();};
async function refreshInstalledModels(){
 if(state.busy){toast('Finish the current generation before refreshing models.');return;}if(!state.connected){openConnection();return;}if(browserState.refreshing)return;browserState.refreshing=true;$('refresh-error').hidden=true;renderModelBrowser();
 try{const response=await fetch(state.server+'/object_info/CheckpointLoaderSimple',{signal:AbortSignal.timeout(10000),cache:'no-store'});if(!response.ok)throw Error(`Server returned ${response.status}.`);const result=await response.json();const models=result.CheckpointLoaderSimple?.input?.required?.ckpt_name?.[0];if(!Array.isArray(models))throw Error('The server did not return a checkpoint list.');const selected=$('model').value;state.models=models;populateInstalledPicker(selected);window.onModelSelectionChange();setModelCollection('installed');renderSetupTutorial();toast(models.length?`${models.length} checkpoints found on your server.`:'No checkpoints found. Check the folder in the setup guide.');}
 catch(error){$('refresh-error').textContent='Could not refresh. '+(error.name==='TimeoutError'?'The server took too long to respond.':error.message)+' Your previous list is still available. Reconnect if the server address changed.';$('refresh-error').hidden=false;}
 finally{browserState.refreshing=false;renderModelBrowser();}
}
$('refresh-models').onclick=refreshInstalledModels;
function populateInstalledPicker(previous){
 $('model').replaceChildren();const usable=state.models.filter(file=>classifyInstalledModel(file).compatible!==false);
 if(!usable.length){const option=document.createElement('option');option.value='';option.textContent='No compatible checkpoints';$('model').append(option);$('model').disabled=true;$('generate-button').disabled=true;return;}
 for(const file of state.models){const info=classifyInstalledModel(file);const option=document.createElement('option');option.value=file;option.textContent=file;option.disabled=info.compatible===false;$('model').append(option);}
 $('model').value=usable.includes(previous)?previous:usable[0];$('model').disabled=state.busy;$('generate-button').disabled=state.busy;
}
